package phase3.ui;
import phase3.core.*;
import blocks.style.ColorMode;
import menu.settings.AppSettings;
import ui.BlockRenderer;
import javax.swing.*;
import java.awt.*;
import java.util.List;

/** Only paints immutable snapshots; has no reference to a live game engine. */
public final class MatchPanel extends JPanel {
 private volatile MatchSnapshot snapshot;
 public MatchPanel(){setFocusable(true);setBackground(new Color(15,20,32));setPreferredSize(new Dimension(1050,780));}
 public void snapshot(MatchSnapshot value){snapshot=value;repaint();}
 @Override protected void paintComponent(Graphics source){super.paintComponent(source);MatchSnapshot s=snapshot;if(s==null)return;Graphics2D g=(Graphics2D)source.create();try{g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,RenderingHints.VALUE_TEXT_ANTIALIAS_ON);int players=s.second()==null?1:2;int slot=getWidth()/players;int size=Math.max(10,Math.min(AppSettings.getInstance().getScreenSize().getCellSize(),Math.min((slot-150)/10,(getHeight()-125)/20)));drawPlayer(g,s.first(),players==1?"PLAYER":"PLAYER 1",Math.max(15,(slot-(size*10+125))/2),70,size);if(s.second()!=null)drawPlayer(g,s.second(),"PLAYER 2",slot+Math.max(15,(slot-(size*10+125))/2),70,size);g.setColor(Color.WHITE);g.setFont(new Font("Dialog",Font.BOLD,18));String header=s.config().mode()+"  /  "+s.config().difficulty()+(s.config().mode()==MatchMode.TIMED?"   남은 시간 "+String.format("%02d:%02d",s.remainingMillis()/60000,(s.remainingMillis()/1000)%60):"");g.drawString(header,20,30);if(s.paused()||!s.result().isEmpty()){g.setColor(new Color(0,0,0,195));g.fillRect(0,getHeight()/2-65,getWidth(),130);g.setColor(Color.WHITE);g.setFont(new Font("Dialog",Font.BOLD,28));String text=s.paused()?"일시정지 · P 키로 재개":s.result().equals("DRAW")?"무승부":s.second()==null?"GAME OVER":s.result().equals("P1")?"PLAYER 1 승리":"PLAYER 2 승리";g.drawString(text,(getWidth()-g.getFontMetrics().stringWidth(text))/2,getHeight()/2);g.setFont(new Font("Dialog",Font.PLAIN,15));if(!s.result().isEmpty())g.drawString("하단 버튼으로 재경기 또는 메뉴 이동",getWidth()/2-140,getHeight()/2+35);}}finally{g.dispose();}}
 private void drawPlayer(Graphics2D g,PlayerSnapshot p,String title,int x,int y,int size){ColorMode mode=AppSettings.getInstance().getColorMode();g.setColor(new Color(108,205,255));g.setFont(new Font("Dialog",Font.BOLD,17));g.drawString(title,x,y-15);int[][] cells=p.board();g.setColor(Color.BLACK);g.fillRect(x,y,size*10,size*20);for(int r=3;r<cells.length;r++)for(int c=0;c<10;c++)paintCell(g,cells[r][c],x+c*size,y+(r-3)*size,size,mode);PieceSnapshot piece=p.current();if(piece!=null){int[][] shape=piece.cells();for(int r=0;r<shape.length;r++)for(int c=0;c<shape[r].length;c++){int row=piece.y()+r;if(row>=3&&row<23)paintCell(g,shape[r][c],x+(piece.x()+c)*size,y+(row-3)*size,size,mode);}}for(int r:p.clearingRows())if(r>=3){g.setColor(new Color(255,255,255,160));g.fillRect(x,y+(r-3)*size,size*10,size);}g.setColor(new Color(255,255,255,22));for(int i=0;i<=10;i++)g.drawLine(x+i*size,y,x+i*size,y+20*size);for(int i=0;i<=20;i++)g.drawLine(x,y+i*size,x+10*size,y+i*size);int side=x+size*10+14;g.setColor(Color.WHITE);g.setFont(new Font("Dialog",Font.BOLD,13));g.drawString("SCORE "+p.score(),side,y+12);g.drawString("LEVEL "+p.level(),side,y+35);g.drawString("LINES "+p.lines(),side,y+58);g.drawString("NEXT",side,y+95);if(p.next()!=null){int[][] next=p.next().cells();int small=Math.min(size,19);for(int r=0;r<next.length;r++)for(int c=0;c<next[r].length;c++)paintCell(g,next[r][c],side+c*small,y+105+r*small,small,mode);}g.setColor(Color.WHITE);List<int[]> pending=p.pendingRows();g.drawString("공격 대기 "+pending.size()+" / 10",side,y+215);int small=9;for(int r=0;r<pending.size();r++)for(int c=0;c<10;c++)paintCell(g,pending.get(r)[c],side+c*small,y+230+r*small,small,mode);}
 private void paintCell(Graphics2D g,int value,int x,int y,int size,ColorMode mode){if(value!=0)BlockRenderer.drawBoardCell(g,x,y,size,value,mode);}
}
